package router

import (
	"net/http"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/httpserver"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// NewMetricsSidecar returns an *http.Server that serves the Prometheus text
// exposition at /metrics on a dedicated port (default :9100). The server is
// NOT started by this function — the caller (main.go) starts it in a goroutine.
//
// The sidecar is intentionally public (no JWT gate) because Prometheus scrapes
// it unauthenticated from within the cluster — see spec §3 (Path B).
func NewMetricsSidecar(addr string) *http.Server {
	mux := http.NewServeMux()
	mux.Handle("/metrics", observability.MetricsHandler())
	return httpserver.Server(addr, mux)
}


