package router_test

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	chi "github.com/go-chi/chi/v5"
	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	"github.com/zenithflowinc/omnicore-platform/services/ws-gateway/internal/router"
)

// setupMeter registers the Prometheus registry before tests that need metrics.
func setupMeter(t *testing.T) func() {
	t.Helper()
	shutdown, err := observability.SetupMeter(context.Background(), "ws-gateway", "test")
	require.NoError(t, err)
	return func() {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		defer cancel()
		_ = shutdown(ctx)
	}
}

// TestNewMetricsSidecar_ServesPrometheusText asserts the sidecar serves
// text/plain at GET /metrics.
func TestNewMetricsSidecar_ServesPrometheusText(t *testing.T) {
	cleanup := setupMeter(t)
	defer cleanup()

	srv := router.NewMetricsSidecar(":0")
	require.NotNil(t, srv)

	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	rr := httptest.NewRecorder()
	srv.Handler.ServeHTTP(rr, req)

	require.Equal(t, http.StatusOK, rr.Code)
	require.Contains(t, rr.Header().Get("Content-Type"), "text/plain")
}

// TestNewMetricsSidecar_ContainsServiceUp asserts service_up is present.
func TestNewMetricsSidecar_ContainsServiceUp(t *testing.T) {
	cleanup := setupMeter(t)
	defer cleanup()

	srv := router.NewMetricsSidecar(":0")
	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	rr := httptest.NewRecorder()
	srv.Handler.ServeHTTP(rr, req)

	body, _ := io.ReadAll(rr.Body)
	require.Contains(t, string(body), "service_up")
}

// TestNewMetricsSidecar_UnknownPath404 asserts only /metrics is served.
func TestNewMetricsSidecar_UnknownPath404(t *testing.T) {
	cleanup := setupMeter(t)
	defer cleanup()

	srv := router.NewMetricsSidecar(":0")
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	rr := httptest.NewRecorder()
	srv.Handler.ServeHTTP(rr, req)

	require.Equal(t, http.StatusNotFound, rr.Code)
}

// TestNewMetricsSidecar_AddrIsPreserved asserts the addr field is set.
func TestNewMetricsSidecar_AddrIsPreserved(t *testing.T) {
	cleanup := setupMeter(t)
	defer cleanup()

	srv := router.NewMetricsSidecar(":9100")
	require.Equal(t, ":9100", srv.Addr)
}

// TestNewMetricsSidecar_TimeoutsMatchPlatformPosture guards against a future
// hand-rolled &http.Server{...} literal replacing httpserver.Server here. A
// literal that only sets ReadHeaderTimeout — the exact shape this sidecar had
// before adopting httpserver.Server — leaves IdleTimeout unbounded, a
// keep-alive-gap Slowloris exposure on a port Prometheus scrapes
// unauthenticated from within the cluster.
func TestNewMetricsSidecar_TimeoutsMatchPlatformPosture(t *testing.T) {
	cleanup := setupMeter(t)
	defer cleanup()

	srv := router.NewMetricsSidecar(":9100")

	require.Equal(t, time.Duration(0), srv.WriteTimeout)
	require.Equal(t, time.Duration(0), srv.ReadTimeout)
	require.Equal(t, 5*time.Second, srv.ReadHeaderTimeout)
	require.Equal(t, 120*time.Second, srv.IdleTimeout)
}

// TestHTTPMetricsMiddleware_RecordsRequest asserts that after a request through
// the chi router wired with HTTPMetricsMiddleware, omnicore_requests_total
// appears in the /metrics scrape.
func TestHTTPMetricsMiddleware_RecordsRequest(t *testing.T) {
	cleanup := setupMeter(t)
	defer cleanup()

	r := chi.NewRouter()
	r.Use(observability.HTTPMetricsMiddleware())
	r.Get("/healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	rr := httptest.NewRecorder()
	r.ServeHTTP(rr, req)
	require.Equal(t, http.StatusOK, rr.Code)

	// Scrape metrics.
	metricsReq := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	metricsRR := httptest.NewRecorder()
	observability.MetricsHandler().ServeHTTP(metricsRR, metricsReq)
	body, _ := io.ReadAll(metricsRR.Body)
	require.Contains(t, string(body), "omnicore_requests_total",
		"HTTPMetricsMiddleware must record omnicore_requests_total")
}


