// Package router is ws-gateway's in-process fan-out registry.
//
// One Router exists per gateway instance. Every WS session registers a
// Subscription on connect (org_id + session_id + user_id + an outbound
// channel) and Unregisters on disconnect. The shared JetStream
// subscriber calls Dispatch with each delivered Frame; Dispatch routes
// to all sessions in the matching org, applies a user-id filter when
// the frame is user-scoped, and drops frames for sessions whose
// channel is full (slow tab can never stall the shared consumer).
//
// Cross-tenant isolation is the Router's responsibility — there is no
// other place between NATS and the WS write where it could be enforced
// in Pattern B.
//
// Router also retains a small bounded per-org backlog of recently
// dispatched Frames so a session that reconnects can request a replay
// of what it missed (see Backlog) instead of silently losing messages.
// This is a stopgap resume mechanism — an in-memory ring buffer, not a
// durable replay log — scoped deliberately small (see defaultBacklogSize).
package router

import (
	"log/slog"
	"sync"
)

// defaultBacklogSize is the number of recent Frames retained per org for
// resume/replay. This is a bounded, in-memory stopgap — not a durable
// replay log — so a gateway restart, or a disconnect spanning more than
// this many org-wide dispatches, still loses history once the backlog
// wraps.
const defaultBacklogSize = 256

// Frame is the unit the Router delivers to a session's outbound channel.
// The shared subscriber builds one of these from each NATS message and
// passes it to Router.Dispatch.
//
// TargetUserID is non-empty when the upstream publisher set the
// x-user-id NATS header — the Router uses it to deliver only to
// matching sessions within the org. Empty TargetUserID means
// broadcast-to-org.
type Frame struct {
	Subject      string
	PayloadB64   string
	RequestID    string
	TargetUserID string
	// Seq is a per-org, monotonically increasing sequence number assigned
	// by Dispatch (starting at 1). Clients persist the highest Seq they
	// have observed and pass it back on reconnect as a resume cursor
	// (see Router.Backlog) to receive Frames dispatched to their org
	// while they were offline, bounded by the org's backlog capacity.
	Seq int64
}

// Subscription is a single WS session's registration with the Router.
// Out is the buffered chan the per-session writer goroutine drains;
// the Router writes Frames to it non-blockingly (drop on full).
type Subscription struct {
	SessionID string
	UserID    string
	Out       chan<- Frame
}

// orgState is the per-org bookkeeping the Router keeps: live session
// subscriptions plus the org's backlog ring buffer and sequence counter.
type orgState struct {
	sessions map[string]*Subscription
	backlog  []Frame // ring buffer, oldest-first, capped at defaultBacklogSize
	nextSeq  int64   // next Seq value to assign (starts at 1)
}

// Router is the in-process fan-out registry. Methods are safe for
// concurrent use.
type Router struct {
	mu     sync.RWMutex
	orgs   map[string]*orgState
	logger *slog.Logger
}

// New returns an empty Router. logger may be nil — Router falls back
// to slog.Default() in that case.
func New(logger *slog.Logger) *Router {
	if logger == nil {
		logger = slog.Default()
	}
	return &Router{
		orgs:   make(map[string]*orgState),
		logger: logger,
	}
}

// OrgCount returns the number of orgs that currently have at least one
// registered subscription. Test/observability helper.
func (r *Router) OrgCount() int {
	r.mu.RLock()
	defer r.mu.RUnlock()
	n := 0
	for _, st := range r.orgs {
		if len(st.sessions) > 0 {
			n++
		}
	}
	return n
}

// Register adds sub to orgID's session map. If a Subscription with the
// same SessionID is already registered under orgID, it is replaced —
// callers are responsible for closing the old chan if needed (the
// Router never closes a chan it didn't create).
//
// Empty orgID or sub.SessionID is a programmer error; the call is a
// no-op (logged at WARN) so a malformed registration cannot poison
// the routing table.
func (r *Router) Register(orgID string, sub *Subscription) {
	if orgID == "" || sub == nil || sub.SessionID == "" {
		r.logger.Warn("router: invalid Register call",
			"orgID_empty", orgID == "",
			"sub_nil", sub == nil,
			"session_id_empty", sub != nil && sub.SessionID == "")
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	st := r.orgOrCreateLocked(orgID)
	st.sessions[sub.SessionID] = sub
}

// orgOrCreateLocked returns orgID's orgState, creating it if absent.
// Callers must hold r.mu (write lock).
func (r *Router) orgOrCreateLocked(orgID string) *orgState {
	st, ok := r.orgs[orgID]
	if !ok {
		st = &orgState{sessions: make(map[string]*Subscription)}
		r.orgs[orgID] = st
	}
	return st
}

// SessionCount returns the number of sessions registered for orgID.
// Used both as a test/observability helper and by the handler to enforce
// a per-org connection ceiling before accepting a new session.
func (r *Router) SessionCount(orgID string) int {
	r.mu.RLock()
	defer r.mu.RUnlock()
	st, ok := r.orgs[orgID]
	if !ok {
		return 0
	}
	return len(st.sessions)
}

// Unregister removes the session from orgID's map. No-op if the org or
// session is absent. Unlike the prior implementation, the org's backlog
// (and org map entry) is retained even after its last session
// unregisters — a brief resume window must survive a full disconnect,
// so the entry is not evicted here. Long-idle orgs accumulate only a
// bounded backlog (defaultBacklogSize Frames), not an unbounded footprint.
func (r *Router) Unregister(orgID, sessionID string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	st, ok := r.orgs[orgID]
	if !ok {
		return
	}
	delete(st.sessions, sessionID)
}

// Dispatch routes frame to every session under orgID. When
// frame.TargetUserID is non-empty, only sessions with a matching
// UserID receive (org-internal user filter). When it is empty,
// every session in orgID receives.
//
// Per-session writes are non-blocking: if a session's Out channel is
// full, the frame is dropped for that session and counted in the
// returned dropped count, and logged at WARN (so a saturated buffer is
// observable rather than a silent loss). The shared subscriber must
// never be held up by a slow tab — the browser detects the gap on next
// reconnect and can resume via Backlog.
//
// Every dispatched frame (regardless of whether any session was live to
// receive it) is also appended to the org's backlog with a freshly
// assigned Seq, so a session that reconnects moments later can still
// catch up.
//
// Returns (delivered, dropped). The two together equal the number of
// matching sessions visited.
func (r *Router) Dispatch(orgID string, frame Frame) (delivered, dropped int) {
	r.mu.Lock()
	defer r.mu.Unlock()
	st := r.orgOrCreateLocked(orgID)

	st.nextSeq++
	frame.Seq = st.nextSeq
	st.backlog = append(st.backlog, frame)
	if len(st.backlog) > defaultBacklogSize {
		st.backlog = st.backlog[len(st.backlog)-defaultBacklogSize:]
	}

	for _, sub := range st.sessions {
		if frame.TargetUserID != "" && sub.UserID != frame.TargetUserID {
			continue
		}
		select {
		case sub.Out <- frame:
			delivered++
		default:
			dropped++
			r.logger.Warn("router: dropped frame on full channel",
				"org_id", orgID,
				"session_id", sub.SessionID,
				"subject", frame.Subject)
		}
	}
	return delivered, dropped
}

// Backlog returns the Frames dispatched to orgID with Seq greater than
// sinceSeq, filtered to those visible to userID (broadcast frames, i.e.
// TargetUserID == "", plus frames explicitly targeted at userID) — the
// same visibility rule Dispatch applies to live sessions. Used to replay
// missed messages to a session that reconnects with a resume cursor.
//
// Only the last defaultBacklogSize frames dispatched to the org are ever
// retained, so a sinceSeq older than the oldest retained frame silently
// yields a partial (not complete) replay — this is a bounded stopgap,
// not a durable log.
func (r *Router) Backlog(orgID, userID string, sinceSeq int64) []Frame {
	r.mu.RLock()
	defer r.mu.RUnlock()
	st, ok := r.orgs[orgID]
	if !ok {
		return nil
	}
	out := make([]Frame, 0, len(st.backlog))
	for _, f := range st.backlog {
		if f.Seq <= sinceSeq {
			continue
		}
		if f.TargetUserID != "" && f.TargetUserID != userID {
			continue
		}
		out = append(out, f)
	}
	return out
}


