	require.Len(t, u2ch, 0, "user_2 must NOT receive a frame scoped to user_1")
}

func TestDispatch_BroadcastIgnoresUserFilter(t *testing.T) {
	r := New(nil)
	u1ch := make(chan Frame, 1)
	u2ch := make(chan Frame, 1)
	r.Register("org_a", &Subscription{SessionID: "s1", UserID: "user_1", Out: u1ch})
	r.Register("org_a", &Subscription{SessionID: "s2", UserID: "user_2", Out: u2ch})

	// Empty TargetUserID = org-wide broadcast.
	delivered, _ := r.Dispatch("org_a", Frame{Subject: "test.org"})

	require.Equal(t, 2, delivered)
}

func TestDispatch_FullChannelDrops_DoesNotBlockSiblingSessions(t *testing.T) {
	r := New(nil)
	// "slow" session: buffer=1, never drained — second Dispatch must
	// drop for this session. "fast" session: buffer=1, drained inline —
	// receives both frames.
	slow := make(chan Frame, 1)
	fast := make(chan Frame, 1)
	r.Register("org_a", &Subscription{SessionID: "slow", UserID: "u1", Out: slow})
	r.Register("org_a", &Subscription{SessionID: "fast", UserID: "u2", Out: fast})

	// First dispatch fills both buffers (no consumer yet).
	delivered1, dropped1 := r.Dispatch("org_a", Frame{Subject: "first"})
	require.Equal(t, 2, delivered1)
	require.Equal(t, 0, dropped1)

	// Drain only the fast channel — slow stays full.
	require.Equal(t, "first", (<-fast).Subject)

	// Second dispatch: fast accepts (1 of 1 free), slow drops (0 free).
	delivered2, dropped2 := r.Dispatch("org_a", Frame{Subject: "second"})
	require.Equal(t, 1, delivered2)
	require.Equal(t, 1, dropped2)

	// fast received the second frame.
	require.Equal(t, "second", (<-fast).Subject)
	// slow still holds "first" — Dispatch never blocked, never overwrote.
	require.Equal(t, "first", (<-slow).Subject)
}

func TestDispatch_DoesNotBlockOnNoBufferChannel(t *testing.T) {
	r := New(nil)
	// Unbuffered chan with no receiver — Dispatch must not block.
	noBuf := make(chan Frame)
	r.Register("org_a", &Subscription{SessionID: "s1", UserID: "u1", Out: noBuf})

	done := make(chan struct{})
	go func() {
		r.Dispatch("org_a", Frame{Subject: "x"})
		close(done)
	}()

	select {
	case <-done:
		// good — returned without blocking
	case <-time.After(100 * time.Millisecond):
		t.Fatal("Dispatch blocked on a chan with no receiver — channel-overflow drop policy violated")
	}
}

// TestDispatch_NotificationSubject_CrossUserIsolation is a security-gate-adjacent
// test that locks in the per-user isolation primitive for notification events.
//
// Security gate context: this is the per-user analogue of Gate 3 (RLS cross-tenant
// isolation) applied at the WebSocket fan-out layer. Two sessions belonging to the
// same org must NOT both receive a notification frame that is addressed to only one
// of them. The router's TargetUserID filter (router.go:146-148) is the sole
// enforcement point between NATS and the WS write path in Pattern B.
//
// Phase F2 of the top-navbar notifications slice 1 spec
// (docs/superpowers/specs/2026-05-16-notifications-slice-1-design.md).
// The researcher (R6) confirmed no router code change is needed — this test
// confirms the existing filter works correctly for the notification subject shape.
func TestDispatch_NotificationSubject_CrossUserIsolation(t *testing.T) {
	r := New(nil)

	userACh := make(chan Frame, 1)
	userBCh := make(chan Frame, 1)

	// Both sessions belong to the same org — this is the critical setup.
	// An org-wide broadcast would reach both; only the TargetUserID filter
	// should prevent userB from receiving a notification intended for userA.
	r.Register("orgX", &Subscription{SessionID: "session-userA", UserID: "userA", Out: userACh})
	r.Register("orgX", &Subscription{SessionID: "session-userB", UserID: "userB", Out: userBCh})

	// Publish a frame that mirrors the exact shape notifications-svc produces:
	// subject "notifications.user.created.orgX", TargetUserID populated from
	// the NATS x-user-id header (set by the dispatch.SharedSubscriber).
	notifFrame := Frame{
		Subject:      "notifications.user.created.orgX",
		PayloadB64:   "dGVzdA==", // base64("test")
		RequestID:    "req-notif-1",
		TargetUserID: "userA",
	}

	delivered, dropped := r.Dispatch("orgX", notifFrame)

	// Exactly one session should receive the frame.
	require.Equal(t, 1, delivered, "exactly one session (userA) should receive the notification")
	require.Equal(t, 0, dropped, "no drops expected — userA channel has capacity")

	// userA's session MUST have received the frame.
	select {
	case got := <-userACh:
		require.Equal(t, "notifications.user.created.orgX", got.Subject)
		require.Equal(t, "userA", got.TargetUserID)
	default:
		t.Fatal("userA session channel is empty — notification was not delivered to the target user")
	}

	// userB's session MUST NOT have received the frame.
	// Using select-with-default: no goroutine scheduling delay needed because
	// Dispatch is synchronous and the channel is buffered — if userB got a
	// frame it is already in the channel buffer.
	select {
	case <-userBCh:
		t.Fatal("SECURITY VIOLATION: userB received a notification frame addressed to userA " +
			"(same-org cross-user isolation broken)")
	default:
		// Correct: userB's channel is empty.
	}
}

func TestRouter_ConcurrentRegisterUnregisterDispatch_NoRaces(t *testing.T) {
	r := New(nil)

	const (
		nWorkers       = 8
		nIterPerWorker = 200
	)

	var wg sync.WaitGroup

	// Half the workers churn registrations.
	for i := 0; i < nWorkers/2; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for j := 0; j < nIterPerWorker; j++ {
				sessID := fmt.Sprintf("w%d-s%d", workerID, j)
				out := make(chan Frame, 4)
				r.Register("org_a", &Subscription{
					SessionID: sessID,
					UserID:    "u",
					Out:       out,
				})
				// Drain in a goroutine so Dispatch never blocks on a
				// channel that no one is reading.
				go func() {
					for range out {
					}
				}()
				r.Unregister("org_a", sessID)
				close(out)
			}
		}(i)
	}

	// Other half dispatch.
	for i := 0; i < nWorkers/2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < nIterPerWorker; j++ {
				_, _ = r.Dispatch("org_a", Frame{Subject: "test"})
			}
		}()
	}

	wg.Wait()

	// Final state should be empty (every Register paired with Unregister).
	require.Equal(t, 0, r.OrgCount())
}

// TestBacklog_ReturnsFramesAfterCursor confirms the core resume contract:
// Dispatch retains dispatched frames, and Backlog returns only those with
// Seq greater than the caller's cursor — the "replay what I missed since
// I last saw seq N" primitive a reconnecting session relies on.
func TestBacklog_ReturnsFramesAfterCursor(t *testing.T) {
	r := New(nil)
	// No live sessions — Dispatch still must record into the backlog.
	r.Dispatch("org_a", Frame{Subject: "s1"})
	r.Dispatch("org_a", Frame{Subject: "s2"})
	r.Dispatch("org_a", Frame{Subject: "s3"})

	all := r.Backlog("org_a", "any-user", 0)
	require.Len(t, all, 3)
	require.Equal(t, "s1", all[0].Subject)
	require.Equal(t, int64(1), all[0].Seq)
	require.Equal(t, "s3", all[2].Subject)
	require.Equal(t, int64(3), all[2].Seq)

	sinceTwo := r.Backlog("org_a", "any-user", 2)
	require.Len(t, sinceTwo, 1)
	require.Equal(t, "s3", sinceTwo[0].Subject)
}

// TestBacklog_UnknownOrgReturnsNil confirms an org with no dispatch
// history yields an empty (nil) backlog rather than an error or panic.
func TestBacklog_UnknownOrgReturnsNil(t *testing.T) {
	r := New(nil)
	require.Empty(t, r.Backlog("org_ghost", "u1", 0))
}

// TestBacklog_FiltersByTargetUser confirms Backlog applies the same
// per-user visibility rule Dispatch applies to live sessions: a
// user-scoped frame (non-empty TargetUserID) is only replayed to the
// user it was addressed to, and broadcast frames (empty TargetUserID)
// are replayed to everyone. Without this, resume would be a cross-user
// isolation regression relative to live delivery.
func TestBacklog_FiltersByTargetUser(t *testing.T) {
	r := New(nil)
	r.Dispatch("org_a", Frame{Subject: "broadcast"})
	r.Dispatch("org_a", Frame{Subject: "for-user-1", TargetUserID: "user_1"})
	r.Dispatch("org_a", Frame{Subject: "for-user-2", TargetUserID: "user_2"})

	user1Backlog := r.Backlog("org_a", "user_1", 0)
	require.Len(t, user1Backlog, 2, "user_1 sees the broadcast plus its own targeted frame")
	subjects := []string{user1Backlog[0].Subject, user1Backlog[1].Subject}
	require.Contains(t, subjects, "broadcast")
	require.Contains(t, subjects, "for-user-1")
	require.NotContains(t, subjects, "for-user-2")
}

// TestBacklog_CapsAtDefaultBacklogSize confirms the ring buffer only ever
// retains the most recent defaultBacklogSize Frames per org — a
// deliberately bounded stopgap, not a durable replay log.
func TestBacklog_CapsAtDefaultBacklogSize(t *testing.T) {
	r := New(nil)
	for i := 0; i < defaultBacklogSize+10; i++ {
		r.Dispatch("org_a", Frame{Subject: "f"})
	}
	all := r.Backlog("org_a", "u1", 0)
	require.Len(t, all, defaultBacklogSize, "backlog must be capped at defaultBacklogSize")
	// The oldest 10 Frames (Seq 1..10) must have been evicted.
	require.Equal(t, int64(11), all[0].Seq)
}

// TestUnregister_RetainsOrgBacklogAfterLastSessionLeaves confirms the org
// entry (and its backlog) survives a session's Unregister — a brief
// resume window must outlive a full disconnect, otherwise a lone
// session's reconnect could never see what it missed while offline.
func TestUnregister_RetainsOrgBacklogAfterLastSessionLeaves(t *testing.T) {
	r := New(nil)
	r.Register("org_a", &Subscription{SessionID: "s1", UserID: "u1", Out: make(chan Frame, 1)})
	r.Dispatch("org_a", Frame{Subject: "before-disconnect"})
	r.Unregister("org_a", "s1")

	require.Equal(t, 0, r.OrgCount(), "no live sessions left")
	backlog := r.Backlog("org_a", "u1", 0)
	require.Len(t, backlog, 1, "backlog must survive the last session's disconnect")
	require.Equal(t, "before-disconnect", backlog[0].Subject)
}



